Vamos refatorar a parte de *plotting* (desenho no gráfico) para ser 100% compatível com MQL5.

### Código MQL5 Totalmente Corrigido

Por favor, substitua o código anterior por este:

```mql5
//+------------------------------------------------------------------+
//|                         Alert on SMA Touch                       |
//|                     Simples Média Móvel com Alerta               |
//+------------------------------------------------------------------+
#property copyright "Exemplo - Assistente"
#property version   "1.02"
#property strict
#property indicator_chart_window
#property indicator_buffers 1

// --- Configuração de Buffers ---
double SMABuffer[];

// --- Parâmetros de entrada configuráveis ---
input int      SMA_Period = 14;                  // Período da Média Móvel
input double   Sensibilidade = 5;                // Sensibilidade em pontos (distância para alerta)
input bool     Notificacao_Ativa = true;         // Enviar notificação no celular?

// --- Variáveis de estado ---
double PreviousAlertPrice = 0.0; // Preço do último alerta

//+------------------------------------------------------------------+
//| Função de inicialização do indicador                             |
//+------------------------------------------------------------------+
int OnInit()
  {
   // 1. Associa o buffer SMABuffer ao índice 0 do indicador
   SetIndexBuffer(0, SMABuffer, INDICATOR_DATA);

   // 2. Define como este buffer será desenhado: Linha, Sólida, Espessura 2, Cor Azul
   PlotIndexSetInteger(0, PLOT_DRAW_TYPE, DRAW_LINE); 
   PlotIndexSetInteger(0, PLOT_LINE_STYLE, STYLE_SOLID);
   PlotIndexSetInteger(0, PLOT_LINE_WIDTH, 2);
   PlotIndexSetString(0, PLOT_LABEL, "SMA(" + (string)SMA_Period + ")");
   PlotIndexSetInteger(0, PLOT_LINE_COLOR, clrBlue); 

   IndicatorSetString(INDICATOR_SHORTNAME, "SMA Alert (" + (string)SMA_Period + ")");

   return(INIT_SUCCEEDED);
  }

//+------------------------------------------------------------------+
//| Função principal de cálculo                                      |
//+------------------------------------------------------------------+
int OnCalculate(const int rates_total, const int prev_calculated,
                const datetime &time[], const double &open[], const double &high[], 
                const double &low[], const double &close[], const long &tick_volume[], 
                const long &volume[], const int &spread[])
  {
   // Verifica se há dados suficientes
   if (rates_total < SMA_Period) 
      return(0);

   // Calcula a média móvel simples
   SimpleMAOnBuffer(rates_total, prev_calculated, close, SMABuffer);

   // Verifica se é necessário enviar um alerta (usando o último candle)
   if (rates_total > 0)
     {
      CheckAlerts(rates_total, close);
     }

   return(rates_total);
  }

//+------------------------------------------------------------------+
//| Calcula a Média Móvel Simples diretamente no Buffer              |
//+------------------------------------------------------------------+
void SimpleMAOnBuffer(int rates_total, int prev_calculated, const double &price[], double &buffer[])
  {
   // Define o ponto de início do cálculo para otimizar
   int start = (prev_calculated > 0) ? prev_calculated - 1 : SMA_Period;
   if (start < SMA_Period) start = SMA_Period;

   for (int i = start; i < rates_total; i++) 
     {
      double sum = 0.0;
      // Soma os 'SMA_Period' preços anteriores (incluindo o atual para o cálculo)
      for (int j = 0; j < SMA_Period; j++) 
         sum += price[i - j];
      buffer[i] = sum / SMA_Period;
     }
  }

//+------------------------------------------------------------------+
//| Verifica condições para emitir alertas                          |
//+------------------------------------------------------------------+
void CheckAlerts(int rates_total, const double &price[])
  {
   // Usamos o índice do último candle (rates_total - 1)
   int last_index = rates_total - 1;

   // Obtém o preço atual de fechamento e o valor da SMA
   double currentPrice = price[last_index];   
   double smaValue = SMABuffer[last_index];  

   // Calcula a distância absoluta entre o preço e a média
   double distance = MathAbs(currentPrice - smaValue);

   // Compara com a sensibilidade (usando _Point para garantir a precisão do ativo)
   if (distance <= Sensibilidade * _Point)
     {
      // VERIFICAÇÃO DE ALERTA: Previne que o alerta dispare múltiplas vezes no mesmo candle
      // Se o preço atual for igual ao último preço que gerou um alerta, ignoramos.
      if (MathAbs(currentPrice - PreviousAlertPrice) > _Point) 
        {
         // Dispara um alerta visual
         string mensagem = "🔔 Alerta SMA! Preço: " + DoubleToString(currentPrice, _Digits) + " | SMA: " + DoubleToString(smaValue, _Digits);
         Alert(mensagem);

         // Envia notificação ao celular
         if (Notificacao_Ativa)
            SendNotification(mensagem);

         // Atualiza o último preço alertado
         PreviousAlertPrice = currentPrice;
        }
     }
  }
//+------------------------------------------------------------------+
