### Código Simulado da Cobrinha (Lógica em Portugol)

Para que este exemplo funcione, precisaremos simular o "tempo" do jogo usando um laço e assumir que a entrada de direção será fornecida manualmente em cada passo.

```portugol
programa
{
    // Constantes do Jogo
    const inteiro TAMANHO_GRID = 10 // O jogo será em uma grade 10x10

    funcao inicio()
    {
        // --- Variáveis do Jogo ---
        inteiro mapa[TAMANHO_GRID][TAMANHO_GRID] // O campo de jogo (0 = vazio, 1 = cobra, 2 = comida)
        inteiro cobra_x[20], cobra_y[20]      // Posições da cobra (máximo de 20 segmentos)
        inteiro comprimento = 3                  // Comprimento inicial da cobra
        inteiro proximo_comprimento = 3
        inteiro proximo_x, proximo_y              // Próxima posição que a cobra tentará ocupar
        inteiro direcao = 0                       // 0: Cima, 1: Baixo, 2: Esquerda, 3: Direita
        inteiro pontuacao = 0

        // --- Inicialização do Jogo ---
        // Coloca a cobra no centro inicial
        cobra_x[0] = TAMANHO_GRID / 2
        cobra_y[0] = TAMANHO_GRID / 2

        // Inicializa o restante do corpo (apenas para efeito visual, pois começa curta)
        para i de 1 ate comprimento - 1 faca
        {
            cobra_x[i] = cobra_x[0] - i
            cobra_y[i] = cobra_y[0]
        }

        // Coloca a primeira comida em um local aleatório (Simplificado)
        gerar_comida(mapa, TAMANHO_GRID)

        escreva("========================================\n")
        escreva("         JOGO DA COBRINHA (TEXTUAL)       \n")
        escreva("========================================\n")

        // --- LOOP PRINCIPAL DO JOGO ---
        enquanto (verdadeiro)
        {
            // 1. Exibir o Estado do Jogo (SIMULAÇÃO DE RENDERIZAÇÃO)
            exibir_mapa(mapa, TAMANHO_GRID, cobra_x, cobra_y, comprimento, 2)
            escreva("\nPONTUAÇÃO: ", pontuacao, " | Comprimento: ", comprimento, "\n")

            // 2. Input do Usuário (Define a direção)
            escreva("Digite a próxima direção (C/D/E/S): ")
            leia(direcao) // *** ATENÇÃO: Aqui você precisa de um código robusto para ler C, D, E ou S e mapear para 0, 1, 2, 3 ***
            // Para simplificar, vamos forçar uma direção para que o código compile:
            direcao = (direcao % 4) 

            // 3. Calcular a Próxima Posição
            proximo_x = cobra_x[0]
            proximo_y = cobra_y[0]

            se direcao == 0 then // Cima
            {
                proximo_y = proximo_y - 1
            }
            senao se direcao == 1 then // Baixo
            {
                proximo_y = proximo_y + 1
            }
            senao se direcao == 2 then // Esquerda
            {
                proximo_x = proximo_x - 1
            }
            senao // Direita (direcao == 3)
            {
                proximo_x = proximo_x + 1
            }

            // 4. Checagem de Colisão
            se (proximo_x < 0) ou (proximo_x >= TAMANHO_GRID) ou (proximo_y < 0) ou (proximo_y >= TAMANHO_GRID) entao
            {
                escreva("\n!!! GAME OVER: Você bateu na parede! !!!\n")
                pare // Termina o jogo
            }
            senao se colisao_com_corpo(cobra_x, cobra_y, comprimento, proximo_x, proximo_y) entao
            {
                escreva("\n!!! GAME OVER: Você mordeu a própria cauda! !!!\n")
                pare // Termina o jogo
            }
            senao
            {
                // 5. Avançar o Corpo (Movimento)
                // O corpo inteiro desliza uma posição para frente
                para i de comprimento - 1 ate 1 faca
                {
                    cobra_x[i] = cobra_x[i-1]
                    cobra_y[i] = cobra_y[i-1]
                }

                // A cabeça assume a nova posição
                cobra_x[0] = proximo_x
                cobra_y[0] = proximo_y

                // 6. Verificar Comida
                se proximo_x == posicao_x_comida e proximo_y == posicao_y_comida entao
                {
                    // Comida comida: Aumenta o corpo e a pontuação
                    proximo_comprimento = comprimento + 1
                    pontuacao = pontuacao + 10

                    // Gerar nova comida em um local vazio
                    gerar_comida(mapa, TAMANHO_GRID)

                    // Ajusta o comprimento real após o cálculo
                    comprimento = proximo_comprimento
                    proximo_comprimento = comprimento + 1 // Reseta para o próximo
                }
                senao
                {
                    // Se não comeu, o último segmento simplesmente desaparece (diminui o comprimento efetivo)
                    comprimento = comprimento // Mantém o tamanho
                }
            }

            // Pausa Simples (Simula o tempo do jogo)
            // Em ambientes reais, usaríamos 'sleep()'. Em Portugol, isso é difícil sem bibliotecas externas.
            pausa_simulada(500) // Simula uma pausa de 500ms
        }
    }

    // --- FUNÇÕES AUXILIARES ---

    // Função que desenha o mapa atual
    funcao exibir_mapa(mapa[TAMANHO_GRID][TAMANHO_GRID], inteiro tam, inteiro x[], inteiro y[], inteiro tam_cobra, inteiro id_comida)
    {
        escreva("\n--- M A P A ---\n")
        para i de 0 ate tam - 1 faca
        {
            escreva("| ")
            para j de 0 ate tam - 1 faca
            {
                // Verifica se esta célula é parte do corpo da cobra
                logico eh_cobra = falso
                para k de 0 ate tam_cobra - 1 faca
                {
                    se x[k] == j e y[k] == i entao
                    {
                        eh_cobra = verdadeiro
                        pare
                    }
                }

                se eh_cobra entao
                {
                    escreva("[O] ") // O = Corpo da Cobra
                }
                senao se mapa[i][j] == 2 entao
                {
                    escreva("[*] ") // * = Comida
                }
                senao
                {
                    escreva("[ .] ") // . = Vazio
                }
            }
            escreva("|\n")
        }
        escreva("-----------------\n")
    }

    // Verifica se a próxima posição está sendo ocupada por outro segmento da cobra
    funcao logico colisao_com_corpo(inteiro x[], inteiro y[], inteiro tam_cobra, inteiro px, inteiro py)
    {
        para i de 0 ate tam_cobra - 1 faca
        {
            // Não verifica a cabeça contra ela mesma (o movimento só ocorre após a verificação)
            se i != 0 e x[i] == px e y[i] == py entao
            {
                retorne verdadeiro // Colisão detectada
            }
        }
        retorne falso // Sem colisão
    }

    // Gera a comida em um local vazio (Simplificado)
    funcao gerar_comida(mapa[TAMANHO_GRID][TAMANHO_GRID], inteiro tam)
    {
        inteiro pos_x, pos_y
        repita
        {
            pos_x = inteiro(rand() * tam)
            pos_y = inteiro(rand() * tam)
        } enquanto (mapa[pos_y][pos_x] == 1) // Não gera em cima da cobra
        mapa[pos_y][pos_x] = 2 // Marca como comida
        // Armazenamos a posição global da comida para ser usada no loop principal
        posicao_x_comida = pos_x
        posicao_y_comida = pos_y
    }

    // --- Variáveis Globais (Para facilitar o acesso na função gerar_comida) ---
    inteiro posicao_x_comida
    inteiro posicao_y_comida

    // Função de pausa (MOCK/Simulação)
    funcao pausa_simulada(inteiro milissegundos)
    {
        // No Portugol Studio, esta função não existe nativamente.
        // Você precisaria usar um comando de "espera" se ele estiver disponível,
        // ou aceitar que o loop será extremamente rápido, tornando o jogo injogável.
        // Para fins de simulação de lógica, assumimos que ela pausa.
        espera(milissegundos) 
    }
}
